-- A reading copy of the schema the migrations leave: generated by npm run db:schema, not to be run.

create table public.content_reports (
  id uuid default gen_random_uuid() not null,
  user_id uuid default auth.uid(),
  target_kind text not null,
  target_id text not null,
  target_code text,
  target_version integer,
  location jsonb default '{}'::jsonb not null,
  anchor_key text default ''::text not null,
  category text not null,
  comment text not null,
  resolution_id uuid,
  created_at timestamp with time zone default now() not null,
  constraint content_reports_pkey PRIMARY KEY (id),
  constraint content_reports_resolution_id_fkey FOREIGN KEY (resolution_id) REFERENCES public.report_resolutions(id) ON DELETE SET NULL,
  constraint content_reports_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE SET NULL,
  constraint content_reports_anchor_key_check CHECK ((char_length(anchor_key) <= 64)),
  constraint content_reports_category_check CHECK ((category = ANY (ARRAY['fact'::text, 'answer_key'::text, 'text'::text, 'image'::text, 'technical'::text, 'other'::text]))),
  constraint content_reports_comment_check CHECK (((char_length(TRIM(BOTH FROM comment)) >= 1) AND (char_length(TRIM(BOTH FROM comment)) <= 2000))),
  constraint content_reports_location_check CHECK (((jsonb_typeof(location) = 'object'::text) AND (octet_length((location)::text) <= 4000))),
  constraint content_reports_target_code_check CHECK ((char_length(target_code) <= 40)),
  constraint content_reports_target_id_check CHECK (((char_length(target_id) >= 1) AND (char_length(target_id) <= 200))),
  constraint content_reports_target_kind_check CHECK ((target_kind = ANY (ARRAY['card'::text, 'note'::text, 'quiz_question'::text, 'wiki_page'::text, 'gymkana_station'::text, 'site'::text]))),
  constraint content_reports_target_version_check CHECK (((target_version >= 1) AND (target_version <= 100000)))
);

CREATE INDEX content_reports_place ON public.content_reports USING btree (user_id, target_kind, target_id, anchor_key) WHERE (resolution_id IS NULL);
CREATE INDEX content_reports_queue ON public.content_reports USING btree (target_kind, target_id) WHERE (resolution_id IS NULL);
CREATE INDEX content_reports_resolution ON public.content_reports USING btree (resolution_id);
CREATE INDEX content_reports_user_created ON public.content_reports USING btree (user_id, created_at DESC);

alter table public.content_reports enable row level security;

create policy "content reports: read own" on public.content_reports
  as permissive
  for select
  to authenticated
  using (((user_id = ( SELECT auth.uid() AS uid)) AND ( SELECT public.is_allowed_user() AS is_allowed_user)));

grant select on table public.content_reports to authenticated;
grant delete, insert, maintain, references, select, trigger, truncate, update on table public.content_reports to service_role;
